import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { describe, test } from "node:test";
import { fileURLToPath } from "node:url";
import { MAX_CHANGES, MAX_TEXT, keepValidEntries, planChangesSchema } from "../src/plan-change-poller.js";

// The contract between the trip site's group-line route and this poller. The fixture is the REAL route's answer
// (server/living-journey.js), generated by tests/plan-changes-limits.test.js for its two worst cases: a 5,000-character
// title with an odd time, and 230 new items. If the route stops fitting the schema this fails here; if the route changes
// its answer, that test fails until the fixture is regenerated on purpose. No database, so it runs on every CI.
const fixture = JSON.parse(readFileSync(fileURLToPath(new URL("./fixtures/plan-changes-site-response.json", import.meta.url)), "utf8")) as
  { clipped: Record<string, unknown>; capped: Record<string, unknown> };

describe("the site route's real answer fits the poller's STRICT schema", () => {
  for (const name of ["clipped", "capped"] as const) {
    test(`${name}: every key and every entry is accepted as it stands`, () => {
      const parsed = planChangesSchema.safeParse(fixture[name]);
      assert.equal(parsed.success, true, parsed.success ? "" : JSON.stringify(parsed.error.issues.slice(0, 3)));
    });

    test(`${name}: no entry would be dropped, and nothing is over the cap`, () => {
      const changes = (fixture[name] as { changes: unknown[] }).changes;
      const { kept, invalid, surplus } = keepValidEntries(changes);
      assert.deepEqual({ invalid, surplus, kept: kept.length }, { invalid: 0, surplus: 0, kept: changes.length });
    });
  }

  test("the clipped case really is the worst case: text at the limit, and a time the site left out", () => {
    const changes = (fixture.clipped as { changes: Array<{ text_en: string; text_he: string; time: string | null }> }).changes;
    assert.ok(changes.some((c) => c.text_en.length === MAX_TEXT && c.text_he.length === MAX_TEXT));
    assert.ok(changes.some((c) => c.time === null));
  });

  test("the capped case is at the cap and says how many it left out", () => {
    const capped = fixture.capped as { changes: unknown[]; changes_omitted: number };
    assert.equal(capped.changes.length, MAX_CHANGES);
    assert.equal(capped.changes_omitted, 30);
  });

  test("the limits the route restates (400 characters, 200 changes) are the schema's", () => {
    assert.equal(MAX_TEXT, 400);
    assert.equal(MAX_CHANGES, 200);
    const route = readFileSync(fileURLToPath(new URL("../../../server/living-journey.js", import.meta.url)), "utf8");
    assert.match(route, /const MAX_TEXT = 400;/);
    assert.match(route, /const MAX_CHANGES = 200;/);
  });

  test("an entry one character over the limit is the kind the poller drops on its own", () => {
    const { kept, invalid } = keepValidEntries([
      { kind: "added", date: "2099-01-01", time: "10:00", text_en: "x".repeat(MAX_TEXT + 1) },
      { kind: "added", date: "2099-01-01", time: "10:00", text_en: "ok" },
    ]);
    assert.equal(invalid, 1);
    assert.equal(kept.length, 1);
  });
});
